def add_hours_across_date(y, m, d, hh, mm, n_hours):
    import datetime
    dt = datetime.datetime(y, m, d, hh, mm) + datetime.timedelta(hours=n_hours)
    return (dt.year, dt.month, dt.day, dt.hour, dt.minute)

def word_frequency(text):
    tokens = text.split()
    d = {}
    for t in tokens:
        d[t] = d.get(t, 0) + 1
    return d

def top_n_frequent(items, n):
    c = {}
    for it in items:
        c[it] = c.get(it, 0) + 1
    sorted_items = sorted(c.items(), key=lambda x: (-x[1], x[0]))
    return sorted_items[:n]

def group_by_length(words):
    d = {}
    for w in words:
        d.setdefault(len(w), []).append(w)
    for k in d:
        d[k].sort()
    return d

def invert_one_to_many(d):
    result = {}
    for k, v in d.items():
        result.setdefault(v, []).append(k)
    for v in result:
        result[v].sort()
    return result

def merge_sum(d1, d2):
    result = dict(d1)
    for k, v in d2.items():
        result[k] = result.get(k, 0) + v
    return result

def merge_concat_lists(d1, d2):
    result = {}
    for k in d1:
        result[k] = list(d1[k])
    for k, v in d2.items():
        if k in result:
            result[k] = result[k] + list(v)
        else:
            result[k] = list(v)
    return result

def count_items(items):
    d = {}
    for it in items:
        d[it] = d.get(it, 0) + 1
    return d

def count_pairs(pairs):
    d = {}
    for p in pairs:
        t = tuple(p)
        d[t] = d.get(t, 0) + 1
    return d

def histogram_bins(nums, bin_size):
    d = {}
    for num in nums:
        b = (num // bin_size) * bin_size
        d[b] = d.get(b, 0) + 1
    return d

def bucket_by_range(nums, boundaries):
    d = {}
    for num in nums:
        idx = sum(1 for b in boundaries if b <= num)
        d[idx] = d.get(idx, 0) + 1
    return d

def anagram_groups(words):
    d = {}
    for w in words:
        key = ''.join(sorted(w))
        d.setdefault(key, []).append(w)
    for k in d:
        d[k].sort()
    return d

def count_vowels_per_word(words):
    vowels = set('aeiouAEIOU')
    d = {}
    for w in words:
        d[w] = sum(1 for c in w if c in vowels)
    return d
